-- Three sources, no shared identifier. Each issues its own local key.
CREATE TABLE MKTG_CONTACT (
    MKTG_ID    NUMBER(38,0) NOT NULL PRIMARY KEY,
    FULL_NAME  VARCHAR(200),
    STREET     VARCHAR(200),
    CITY       VARCHAR(100),
    STATE_CODE VARCHAR(2),
    ZIP5       VARCHAR(5),
    EMAIL      VARCHAR(255)
);
CREATE TABLE EVENTS_ATTENDEE (
    ATTENDEE_REF VARCHAR(40)  NOT NULL PRIMARY KEY,
    NAME         VARCHAR(200),
    ADDR_LINE1   VARCHAR(200),
    ADDR_CITY    VARCHAR(100),
    ADDR_STATE   VARCHAR(2),
    ADDR_ZIP     VARCHAR(10),
    CONTACT_MAIL VARCHAR(255)
);
CREATE TABLE SUPPORT_PARTY (
    PARTY_KEY  VARCHAR(64)  NOT NULL PRIMARY KEY,
    PARTY_NAME VARCHAR(200),
    STREET     VARCHAR(200),
    CITY       VARCHAR(100),
    REGION     VARCHAR(2),
    POSTCODE   VARCHAR(10),
    EMAIL_ADDR VARCHAR(255)
);
